import React from 'react'

export default function PunkBg({ children }) {
  return (
    <div className="relative min-h-screen w-full bg-black  z-0">
      {/* Stars in top half - white only, more visible */}
      {/* Stars in top half - white only, random placement */}
        <div className="fixed inset-0 overflow-hidden" style={{ height: '55vh', zIndex: -10 }}>
        {/* Random scattered stars using individual positioned dots */}
        <div 
            className="absolute inset-0"
            style={{
            backgroundImage: `
                radial-gradient(circle at 15% 10%, white 1px, transparent 1px),
                radial-gradient(circle at 45% 25%, white 1.5px, transparent 1.5px),
                radial-gradient(circle at 78% 15%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 32% 45%, white 1px, transparent 1px),
                radial-gradient(circle at 88% 35%, white 1px, transparent 1px),
                radial-gradient(circle at 62% 55%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 25% 70%, white 1.5px, transparent 1.5px),
                radial-gradient(circle at 90% 65%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 8% 80%, white 1px, transparent 1px),
                radial-gradient(circle at 55% 85%, white 1px, transparent 1px),
                radial-gradient(circle at 70% 75%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 12% 35%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 50% 12%, white 1px, transparent 1px),
                radial-gradient(circle at 95% 50%, white 1.5px, transparent 1.5px),
                radial-gradient(circle at 38% 60%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 82% 90%, white 1px, transparent 1px),
                radial-gradient(circle at 20% 52%, white 1px, transparent 1px),
                radial-gradient(circle at 65% 8%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 42% 92%, white 1.5px, transparent 1.5px),
                radial-gradient(circle at 5% 48%, white 0.5px, transparent 0.5px)
            `,
            backgroundSize: '100% 100%',
            backgroundRepeat: 'no-repeat',
            opacity: 0.8
            }}
        />
        
        {/* More scattered stars - second layer for depth */}
        <div 
            className="absolute inset-0"
            style={{
            backgroundImage: `
                radial-gradient(circle at 28% 18%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 72% 28%, white 1px, transparent 1px),
                radial-gradient(circle at 18% 62%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 85% 78%, white 1px, transparent 1px),
                radial-gradient(circle at 52% 40%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 92% 22%, white 1.5px, transparent 1.5px),
                radial-gradient(circle at 35% 88%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 68% 95%, white 1px, transparent 1px),
                radial-gradient(circle at 10% 58%, white 1px, transparent 1px),
                radial-gradient(circle at 58% 32%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 75% 48%, white 1.5px, transparent 1.5px),
                radial-gradient(circle at 22% 78%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 48% 68%, white 1px, transparent 1px),
                radial-gradient(circle at 3% 25%, white 0.5px, transparent 0.5px),
                radial-gradient(circle at 97% 42%, white 1px, transparent 1px)
            `,
            backgroundSize: '100% 100%',
            backgroundRepeat: 'no-repeat',
            opacity: 0.7
            }}
        />
        
        {/* Larger glowing stars - fewer, brighter */}
        <div 
            className="absolute inset-0"
            style={{
            backgroundImage: `
                radial-gradient(circle at 20% 25%, rgba(255,255,255,0.9) 0%, transparent 4px),
                radial-gradient(circle at 70% 40%, rgba(255,255,255,0.9) 0%, transparent 4px),
                radial-gradient(circle at 45% 65%, rgba(255,255,255,0.9) 0%, transparent 4px),
                radial-gradient(circle at 85% 20%, rgba(255,255,255,0.9) 0%, transparent 4px),
                radial-gradient(circle at 60% 80%, rgba(255,255,255,0.9) 0%, transparent 4px)
            `,
            backgroundSize: '100% 100%',
            backgroundRepeat: 'no-repeat',
            filter: 'blur(1px)',
            opacity: 0.6
            }}
        />
        </div>

      
      {/* Grid starts at middle (55vh) and goes down */}
      <div className="fixed inset-0 overflow-hidden" style={{ top: '55vh', zIndex: -10 }}>
        <div style={{ perspective: '1000px', height: '100%' }}>
          <div 
            className="absolute inset-0" 
            style={{ 
              transform: 'rotateX(75deg)',
              transformOrigin: 'center top'
            }}
          >
            <div 
              className="absolute animate-grid"
              style={{
                left: '-50%',
                width: '200%',
                height: '300vh',
                backgroundImage: 'linear-gradient(to right, rgba(236,0,0,0.4) 1px, transparent 1px), linear-gradient(to bottom, rgba(6,182,212,0.6) 1px, transparent 1px)',
                backgroundSize: '40px 40px',
                transformOrigin: 'center top',
                maskImage: 'linear-gradient(to bottom, transparent 0%, black 8%, black 100%)',
                WebkitMaskImage: 'linear-gradient(to bottom, transparent 0%, black 8%, black 100%)'
              }}
            />
          </div>
        </div>
        
        {/* Enhanced fade at horizon */}
        <div 
          className="absolute inset-0 pointer-events-none" 
          style={{
            background: 'linear-gradient(to bottom, black 0%, transparent 12%, transparent 70%, black 100%)'
          }}
        />
      </div>
      
      {/* Horizon glow at middle */}
      <div className="fixed left-0 right-0 h-32 blur-2xl" style={{ top: '55vh', zIndex: -10, background: 'linear-gradient(to bottom, rgba(236,72,153,0.3), rgba(6,182,212,0.2), transparent)' }} />
      
      {/* Content */}
      <div className="relative z-10">
        {children}
      </div>
    </div>
  )
}
